<script setup>
import { ref, reactive, computed, onMounted, onBeforeUnmount, nextTick } from 'vue'; import axios from 'axios'; import * as echarts from 'echarts'; import { ElMessage, ElMessageBox } from 'element-plus';
const token=ref(localStorage.getItem('weather_token')); const user=ref(JSON.parse(localStorage.getItem('weather_user')||'null')); const loginForm=reactive({username:'admin',password:'123456'}); const registerMode=ref(false); const loginRole=ref('admin'); const loginError=ref('');
const api=axios.create({baseURL:'/api'}); api.interceptors.request.use(c=>{if(token.value)c.headers.Authorization=`Bearer ${token.value}`;return c});
const loading=ref(false); const loginBusy=ref(false); const mobileNavOpen=ref(false); const chartInstance=ref(null);
const page=ref('dashboard'); const devices=ref([]), deviceTotal=ref(0), stations=ref([]), maintains=ref([]), notices=ref([]), weather=ref([]), alerts=ref([]), plans=ref([]), logs=ref([]), analytics=reactive({byStatus:[],byType:[],weather:[],alerts:0}); const stats=reactive({deviceTotal:0,faultTotal:0,maintainTotal:0,stationTotal:0,alertTotal:0,planDue:0}); const chart=ref(null);
const filters=reactive({keyword:'',status:'',type:'',page:1,size:8}); const deviceDialog=ref(false); const detailDialog=ref(false); const stationDialog=ref(false); const maintainDialog=ref(false); const weatherDialog=ref(false); const planDialog=ref(false); const editing=ref(false); const detailData=reactive({device:null,maintains:[],weather:[]}); const deviceForm=reactive({id:null,code:'',name:'',type:'温度',model:'',manufacturer:'',stationId:null,purchaseDate:'',status:'normal',remark:''}); const stationForm=reactive({name:'',address:'',longitude:114.396,latitude:30.55,manager:''}); const maintainForm=reactive({deviceId:1,faultDescription:'',content:'',cost:0,maintainer:''}); const weatherForm=reactive({deviceId:1,temperature:25,humidity:60,windSpeed:2,rainfall:0,pressure:1005}); const planForm=reactive({deviceId:1,title:'设备定期保养',cycleDays:30,nextDate:'',owner:'',remark:'定期检查设备运行状态'});
const menu=computed(()=>[{key:'dashboard',label:'运行总览',icon:'Odometer'},{key:'devices',label:'设备台账',icon:'Monitor'},{key:'stations',label:'气象站点',icon:'Location'},{key:'maintains',label:'维修工单',icon:'Tools'},{key:'plans',label:'保养计划',icon:'Calendar'},{key:'weather',label:'采集数据',icon:'DataLine'},{key:'alerts',label:'告警中心',icon:'Warning'},{key:'analytics',label:'数据分析',icon:'TrendCharts'},{key:'logs',label:'操作日志',icon:'Document'} ,{key:'notices',label:'公告通知',icon:'Bell'}].filter(x=>user.value?.role==='viewer'?['dashboard','devices','stations','weather','analytics','notices'].includes(x.key):true));
async function doLogin(){if(loginBusy.value)return;loginBusy.value=true;loginError.value='';try{const r=await api.post(registerMode.value?'/auth/register':'/auth/login',loginForm);if(registerMode.value){registerMode.value=false;loginError.value='注册成功，请登录';return} token.value=r.data.token;user.value=r.data.user;localStorage.setItem('weather_token',token.value);localStorage.setItem('weather_user',JSON.stringify(user.value));await load()}catch(e){loginError.value=e.response?.data?.message||'请求失败，请检查服务是否已启动'}finally{loginBusy.value=false}}
function switchLoginRole(role){loginRole.value=role;registerMode.value=false;loginError.value='';loginForm.username=role==='admin'?'admin':'';loginForm.password=role==='admin'?'123456':''}
function logout(){token.value=null;user.value=null;localStorage.clear()}
async function load(){if(!token.value)return;loading.value=true;try{if(page.value==='dashboard'){const r=await api.get('/dashboard');Object.assign(stats,r.data);weather.value=r.data.weather||[];nextTick(drawChart)} if(page.value==='devices'){const r=await api.get('/devices',{params:filters});devices.value=r.data.records;deviceTotal.value=r.data.total} if(page.value==='stations')stations.value=(await api.get('/stations')).data; if(page.value==='maintains')maintains.value=(await api.get('/maintains')).data; if(page.value==='plans')plans.value=(await api.get('/plans')).data; if(page.value==='weather')weather.value=(await api.get('/weather')).data; if(page.value==='alerts')alerts.value=(await api.get('/alerts')).data; if(page.value==='analytics')Object.assign(analytics,(await api.get('/analytics')).data); if(page.value==='logs')logs.value=(await api.get('/logs')).data; if(page.value==='notices')notices.value=(await api.get('/notices')).data}catch(e){ElMessage.error(e.response?.data?.message||'数据加载失败，请稍后重试')}finally{loading.value=false}}
function drawChart(){if(!chart.value)return;chartInstance.value=chartInstance.value||echarts.init(chart.value);chartInstance.value.setOption({animation:!window.matchMedia('(prefers-reduced-motion: reduce)').matches,aria:{enabled:true,description:'最近采集记录的温度变化趋势'},tooltip:{trigger:'axis'},legend:{show:true,data:['温度'],right:8,top:0},grid:{left:42,right:18,top:34,bottom:30},xAxis:{type:'category',data:weather.value.map(x=>String(x.collectTime||'').slice(11,16)),axisLabel:{color:'#718292'}},yAxis:{type:'value',name:'°C',nameTextStyle:{color:'#718292'},axisLabel:{color:'#718292'},splitLine:{lineStyle:{color:'#e8eef1'}}},series:[{name:'温度',type:'line',smooth:true,data:weather.value.map(x=>x.temperature),lineStyle:{color:'#0f8f86',width:2},itemStyle:{color:'#0f8f86'},areaStyle:{color:'rgba(15,143,134,.12)'}}]})}
function openDevice(d){editing.value=!!d;Object.assign(deviceForm,d||{id:null,code:'',name:'',type:'温度',model:'',manufacturer:'',stationId:null,purchaseDate:'',status:'normal',remark:''});deviceDialog.value=true}
async function saveDevice(){if(!deviceForm.code?.trim()){ElMessage.warning('请输入设备编号');return}if(!deviceForm.name?.trim()){ElMessage.warning('请输入设备名称');return}try{if(editing.value)await api.put('/devices/'+deviceForm.id,deviceForm);else await api.post('/devices',deviceForm);deviceDialog.value=false;ElMessage.success('保存成功');filters.page=1;await load()}catch(e){ElMessage.error(e.response?.data?.message||'保存失败')}}
async function openDetail(id){Object.assign(detailData,await api.get('/devices/'+id+'/detail').then(r=>r.data));detailDialog.value=true}
async function exportDevices(){const r=await api.get('/devices/export',{responseType:'blob'});const url=URL.createObjectURL(r.data);const a=document.createElement('a');a.href=url;a.download='devices.csv';a.click();URL.revokeObjectURL(url)}
async function removeDevice(id){try{await ElMessageBox.confirm('删除后将无法在台账中恢复该设备，是否继续？','确认删除',{type:'warning',confirmButtonText:'删除设备',cancelButtonText:'取消'});await api.delete('/devices/'+id);ElMessage.success('设备已删除');await load()}catch(e){if(e!=='cancel')ElMessage.error(e.response?.data?.message||'删除失败')}}
async function addNotice(){const title=prompt('公告标题');const content=prompt('公告内容');if(title)await api.post('/notices',{title,content});load()}
function addStation(){Object.assign(stationForm,{name:'',address:'',longitude:114.396,latitude:30.55,manager:''});stationDialog.value=true}
async function saveStation(){if(!stationForm.name.trim())return;await api.post('/stations',stationForm);stationDialog.value=false;await load()}
function addMaintain(){Object.assign(maintainForm,{deviceId:1,faultDescription:'',content:'',cost:0,maintainer:user.value?.name||user.value?.username||''});maintainDialog.value=true}
async function saveMaintain(){if(!maintainForm.deviceId||!maintainForm.faultDescription.trim())return;await api.post('/maintains',maintainForm);maintainDialog.value=false;await load()}
function simulateWeather(){Object.assign(weatherForm,{deviceId:1,temperature:Number((20+Math.random()*12).toFixed(1)),humidity:Number((45+Math.random()*35).toFixed(1)),windSpeed:Number((1+Math.random()*5).toFixed(1)),rainfall:0,pressure:Number((1000+Math.random()*15).toFixed(1))});weatherDialog.value=true}
async function saveWeather(){if(!weatherForm.deviceId)return;await api.post('/weather/simulate',weatherForm);weatherDialog.value=false;await load()}
async function ackAlert(id){await api.put('/alerts/'+id+'/ack');await load()}
function goMaintain(){page.value='maintains';load()}
function addPlan(){Object.assign(planForm,{deviceId:1,title:'设备定期保养',cycleDays:30,nextDate:new Date(Date.now()+30*86400000).toISOString().slice(0,10),owner:user.value?.name||user.value?.username||'',remark:'定期检查设备运行状态'});planDialog.value=true}
async function savePlan(){if(!planForm.deviceId||!planForm.title.trim())return;await api.post('/plans',planForm);planDialog.value=false;await load()}
function navigate(nextPage){page.value=nextPage;mobileNavOpen.value=false;load()}
function resizeChart(){chartInstance.value?.resize()}
onMounted(()=>{load();window.addEventListener('resize',resizeChart)})
onBeforeUnmount(()=>{window.removeEventListener('resize',resizeChart);chartInstance.value?.dispose()})
</script>
<template>
<a href="#main-content" class="skip-link">跳转到主要内容</a><div v-if="!token" class="login-page"><div class="weather-scene" aria-hidden="true"><div class="weather-orbit orbit-one"></div><div class="weather-orbit orbit-two"></div><div class="cloud cloud-a"></div><div class="cloud cloud-b"></div><div class="rain-lines"></div></div><div class="weather-meta" aria-label="当前气象摘要"><div><strong>26.8°</strong><span>当前温度</span></div><div><strong>68%</strong><span>相对湿度</span></div><div><strong>2.6 m/s</strong><span>风速</span></div></div><div class="login-card"><div class="brand-mark" aria-hidden="true">WX</div><h1>气象设备管理平台</h1><p class="sub">Meteorological Operations Center</p><div class="login-role-switch" role="tablist" aria-label="登录身份"><button type="button" role="tab" :aria-selected="loginRole==='admin'" :class="{active:loginRole==='admin'}" @click="switchLoginRole('admin')"><el-icon aria-hidden="true"><Lock /></el-icon>系统管理员</button><button type="button" role="tab" :aria-selected="loginRole==='user'" :class="{active:loginRole==='user'}" @click="switchLoginRole('user')"><el-icon aria-hidden="true"><User /></el-icon>普通用户</button></div><div class="login-context">{{loginRole==='admin'?'管理员专属入口':'用户服务入口'}}</div><el-form @submit.prevent="doLogin"><el-form-item label="用户名" label-position="top"><el-input v-model="loginForm.username" size="large" autocomplete="username" placeholder="请输入用户名"><template #prefix><el-icon aria-hidden="true"><User /></el-icon></template></el-input></el-form-item><el-form-item label="密码" label-position="top"><el-input v-model="loginForm.password" size="large" type="password" autocomplete="current-password" show-password placeholder="请输入密码" @keyup.enter="doLogin"><template #prefix><el-icon aria-hidden="true"><Lock /></el-icon></template></el-input></el-form-item><el-button class="login-btn" size="large" type="primary" native-type="submit" :loading="loginBusy">{{registerMode?'注册普通用户':'进入系统'}} <el-icon v-if="!loginBusy" aria-hidden="true"><ArrowRight /></el-icon></el-button></el-form><div class="login-tip" :class="{error:loginError && !loginError.includes('成功')}" role="status" aria-live="polite">{{loginError||(loginRole==='admin'?'管理员演示账号：admin / 123456':'普通用户可注册或使用 viewer / 123456')}}</div><button v-if="loginRole==='user'" type="button" class="text-action" @click="registerMode=!registerMode">{{registerMode?'返回用户登录':'注册普通用户'}}</button></div></div>
<div v-else class="app-shell" :class="{'nav-open':mobileNavOpen}"><button class="mobile-scrim" type="button" aria-label="关闭导航菜单" @click="mobileNavOpen=false"></button><aside><div class="logo"><span aria-hidden="true">WX</span><div>气象云平台<small>OPERATIONS CENTER</small></div><button class="mobile-close" type="button" aria-label="关闭导航菜单" @click="mobileNavOpen=false"><el-icon><Close /></el-icon></button></div><div class="station-chip"><span class="pulse" aria-hidden="true"></span> 系统运行正常</div><nav aria-label="主导航"><button v-for="item in menu" :key="item.key" type="button" :class="['nav-item',{active:page===item.key}]" :aria-current="page===item.key?'page':undefined" @click="navigate(item.key)"><el-icon aria-hidden="true"><component :is="item.icon" /></el-icon><span>{{item.label}}</span><span v-if="item.key==='devices' && deviceTotal" class="nav-count" aria-label="设备数量">{{deviceTotal}}</span></button></nav><div class="aside-bottom"><div class="profile"><el-avatar :size="36">{{user.name?.slice(0,1)||'管'}}</el-avatar><div><b>{{user.name||user.username}}</b><small>{{user.role==='admin'?'系统管理员':user.role==='maintainer'?'设备维护员':'查看用户'}}</small></div><button class="logout-button" type="button" aria-label="退出登录" @click="logout"><el-icon><SwitchButton /></el-icon></button></div></div></aside><main id="main-content" tabindex="-1" :aria-busy="loading"><header><button class="mobile-menu" type="button" aria-label="打开导航菜单" :aria-expanded="mobileNavOpen" @click="mobileNavOpen=true"><el-icon><Expand /></el-icon></button><div><span class="eyebrow">LIVE MONITORING</span><h2>{{menu.find(x=>x.key===page)?.label}}</h2></div><div class="header-right"><div class="header-weather"><el-icon aria-hidden="true"><Sunny /></el-icon><span><b>26.8°C</b><small>晴间多云</small></span><i></i><span><b>2.6 m/s</b><small>东南风</small></span></div><span class="time">{{new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric'})}}</span><el-badge :value="stats.faultTotal" :hidden="!stats.faultTotal" type="danger"><el-button circle aria-label="查看告警"><el-icon aria-hidden="true"><Bell /></el-icon></el-button></el-badge></div></header><section v-if="page==='dashboard'" class="content"><div class="weather-banner"><div class="weather-banner-main"><div class="weather-icon"><el-icon aria-hidden="true"><MostlyCloudy /></el-icon></div><div><span>东湖气象站 · 实时观测</span><strong>26.8<sup>°C</sup></strong><small>体感舒适，设备数据每分钟更新</small></div></div><div class="weather-banner-data"><div><el-icon aria-hidden="true"><Drizzling /></el-icon><span>湿度<b>68%</b></span></div><div><el-icon aria-hidden="true"><WindPower /></el-icon><span>风速<b>2.6 m/s</b></span></div><div><el-icon aria-hidden="true"><Odometer /></el-icon><span>气压<b>1007.5 hPa</b></span></div></div></div><div class="metric-grid"><div class="metric teal"><span>设备总数</span><strong>{{stats.deviceTotal}}</strong><small>台 · 覆盖 {{stats.stationTotal}} 个站点</small><el-icon aria-hidden="true"><Monitor /></el-icon></div><div class="metric orange"><span>故障设备</span><strong>{{stats.faultTotal}}</strong><small>台 · 需要关注</small><el-icon aria-hidden="true"><Warning /></el-icon></div><div class="metric blue"><span>维修记录</span><strong>{{stats.maintainTotal}}</strong><small>次 · 累计维护</small><el-icon aria-hidden="true"><Tools /></el-icon></div><div class="metric purple"><span>数据采集</span><strong>{{weather.length}}</strong><small>条 · 最新数据</small><el-icon aria-hidden="true"><DataLine /></el-icon></div></div><div class="dashboard-grid"><div class="panel chart-panel"><div class="panel-head"><div><b>温度趋势</b><small>最近 12 条采集记录</small></div><el-tag type="success">实时</el-tag></div><div ref="chart" class="chart" role="img" aria-label="最近采集记录的温度变化趋势"></div></div><div class="panel status-panel"><div class="panel-head"><div><b>设备状态</b><small>按运行状态统计</small></div></div><div class="status-ring"><div class="ring"><strong>{{stats.deviceTotal?Math.round((stats.deviceTotal-stats.faultTotal)/stats.deviceTotal*100):0}}<sup>%</sup></strong><span>正常率</span></div><div class="legend"><span><i class="dot normal"></i>正常 <b>{{stats.deviceTotal-stats.faultTotal}}</b></span><span><i class="dot fault"></i>故障 <b>{{stats.faultTotal}}</b></span><span><i class="dot repair"></i>维修 <b>0</b></span></div></div></div></div><div class="panel notice-strip"><div class="panel-head"><div><b>最新公告</b><small>平台通知</small></div><el-button link @click="navigate('notices')">查看全部 <el-icon aria-hidden="true"><ArrowRight /></el-icon></el-button></div><div v-if="notices[0]" class="notice-row"><el-icon aria-hidden="true"><BellFilled /></el-icon><span>{{notices[0].title}}</span><time>{{String(notices[0].publishTime||'').slice(0,10)}}</time></div><div v-else class="empty">暂无公告</div></div></section>
<section v-else class="content"><div v-if="page==='devices'" class="panel table-panel"><div class="toolbar"><div class="filters"><el-input v-model="filters.keyword" placeholder="搜索编号或设备名称" clearable @keyup.enter="load" style="width:220px"><template #prefix><el-icon><Search /></el-icon></template></el-input><el-select v-model="filters.status" placeholder="运行状态" clearable @change="load"><el-option label="正常" value="normal"/><el-option label="故障" value="fault"/><el-option label="维修" value="repair"/><el-option label="停用" value="disabled"/></el-select><el-select v-model="filters.type" placeholder="设备类型" clearable @change="load"><el-option label="温度" value="温度"/><el-option label="雨量" value="雨量"/><el-option label="风速" value="风速"/><el-option label="气压" value="气压"/></el-select></div><el-button @click="exportDevices"><el-icon><Download /></el-icon>导出</el-button><el-button v-if="user.role!=='viewer'" type="primary" @click="openDevice()"><el-icon><Plus /></el-icon>新增设备</el-button></div><el-table :data="devices" stripe><el-table-column prop="code" label="设备编号" width="130"/><el-table-column prop="name" label="设备名称" min-width="180"/><el-table-column prop="type" label="类型" width="90"/><el-table-column prop="manufacturer" label="生产厂家"/><el-table-column prop="model" label="型号"/><el-table-column prop="status" label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='normal'?'success':row.status==='fault'?'danger':'warning'">{{row.status==='normal'?'正常':row.status==='fault'?'故障':row.status==='repair'?'维修':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="140" v-if="user.role!=='viewer'"><template #default="{row}"><el-button link @click="openDetail(row.id)">详情</el-button><el-button link type="primary" @click="openDevice(row)">编辑</el-button><el-button link type="danger" @click="removeDevice(row.id)">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="filters.page" :page-size="filters.size" :total="deviceTotal" layout="total, prev, pager, next" @current-change="load"/></div><div v-else-if="page==='stations'" class="panel table-panel"><div class="toolbar"><b>气象站点</b><el-button type="primary" @click="addStation">新增站点</el-button></div><el-table :data="stations" stripe><el-table-column prop="name" label="站点名称"/><el-table-column prop="address" label="地址"/><el-table-column prop="longitude" label="经度"/><el-table-column prop="latitude" label="纬度"/><el-table-column prop="manager" label="负责人"/></el-table></div><div v-else-if="page==='maintains'" class="panel table-panel"><div class="toolbar"><b>维修工单</b><el-button type="primary" @click="addMaintain">新建工单</el-button></div><el-table :data="maintains" stripe><el-table-column prop="deviceId" label="设备 ID" width="100"/><el-table-column prop="faultDescription" label="故障描述"/><el-table-column prop="maintainer" label="维修人员"/><el-table-column prop="reportTime" label="报修时间"/><el-table-column prop="cost" label="费用"/><el-table-column prop="result" label="维修结果"/></el-table></div><div v-else-if="page==='weather'" class="panel table-panel"><div class="toolbar"><b>气象采集数据</b><el-button type="primary" @click="simulateWeather">模拟上传</el-button></div><el-table :data="weather" stripe><el-table-column prop="collectTime" label="采集时间"/><el-table-column prop="deviceId" label="设备 ID"/><el-table-column prop="temperature" label="温度 (°C)"/><el-table-column prop="humidity" label="湿度 (%)"/><el-table-column prop="windSpeed" label="风速 (m/s)"/><el-table-column prop="rainfall" label="降雨量 (mm)"/><el-table-column prop="pressure" label="气压 (hPa)"/></el-table></div><div v-else-if="page==='plans'" class="panel table-panel"><div class="toolbar"><b>保养计划</b><el-button type="primary" @click="addPlan">新增计划</el-button></div><el-table :data="plans" stripe><el-table-column prop="title" label="计划名称"/><el-table-column prop="deviceId" label="设备 ID" width="100"/><el-table-column prop="cycleDays" label="周期(天)" width="100"/><el-table-column prop="nextDate" label="下次保养"/><el-table-column prop="owner" label="负责人"/><el-table-column prop="status" label="状态"/></el-table></div><div v-else-if="page==='alerts'" class="panel table-panel"><div class="toolbar"><b>设备告警中心</b><el-tag type="danger">{{alerts.filter(x=>x.status==='open').length}} 条未处理</el-tag></div><el-table :data="alerts" stripe><el-table-column prop="level" label="级别"/><el-table-column prop="type" label="类型"/><el-table-column prop="deviceId" label="设备 ID"/><el-table-column prop="message" label="告警内容"/><el-table-column prop="createdAt" label="时间"/><el-table-column label="操作"><template #default="{row}"><template v-if="row.status==='open'"><el-button link type="primary" @click="goMaintain">去处理</el-button><el-button link type="danger" @click="ackAlert(row.id)">关闭</el-button></template><span v-else>已关闭</span></template></el-table-column></el-table></div><div v-else-if="page==='analytics'" class="panel table-panel"><div class="toolbar"><b>数据分析</b><el-tag type="success">实时统计</el-tag></div><div class="analysis-cards"><div><small>设备类型</small><strong>{{analytics.byType.length}}</strong></div><div><small>气象记录</small><strong>{{analytics.weather.length}}</strong></div><div><small>未处理告警</small><strong>{{analytics.alerts}}</strong></div></div><el-table :data="analytics.byType" stripe><el-table-column prop="type" label="设备类型"/><el-table-column prop="total" label="设备数量"/></el-table></div><div v-else-if="page==='logs'" class="panel table-panel"><div class="toolbar"><b>操作日志</b><span class="muted">最近 100 条记录</span></div><el-table :data="logs" stripe><el-table-column prop="operator" label="操作人"/><el-table-column prop="action" label="操作内容"/><el-table-column prop="target" label="操作对象"/><el-table-column prop="operateTime" label="操作时间"/><el-table-column prop="ip" label="IP 地址"/></el-table></div><div v-else class="panel table-panel"><div class="toolbar"><b>公告通知</b><el-button type="primary" @click="addNotice">发布公告</el-button></div><div v-for="n in notices" :key="n.id" class="notice-card"><div class="notice-icon"><el-icon><BellFilled /></el-icon></div><div><h3>{{n.title}}</h3><p>{{n.content}}</p><small>{{n.publisher}} · {{String(n.publishTime||'').slice(0,16).replace('T',' ')}}</small></div></div></div></section></main></div>
<el-dialog v-model="deviceDialog" :title="editing ? '编辑设备' : '新增设备'" width="560px"><el-form label-width="90px"><el-form-item label="设备编号"><el-input v-model="deviceForm.code"/></el-form-item><el-form-item label="设备名称"><el-input v-model="deviceForm.name"/></el-form-item><el-form-item label="设备类型"><el-select v-model="deviceForm.type"><el-option label="温度" value="温度"/><el-option label="湿度" value="湿度"/><el-option label="风速" value="风速"/><el-option label="雨量" value="雨量"/><el-option label="气压" value="气压"/></el-select></el-form-item><el-form-item label="型号"><el-input v-model="deviceForm.model"/></el-form-item><el-form-item label="生产厂家"><el-input v-model="deviceForm.manufacturer"/></el-form-item><el-form-item label="运行状态"><el-select v-model="deviceForm.status"><el-option label="正常" value="normal"/><el-option label="故障" value="fault"/><el-option label="维修" value="repair"/><el-option label="停用" value="disabled"/></el-select></el-form-item><el-form-item label="备注"><el-input v-model="deviceForm.remark" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="deviceDialog=false">取消</el-button><el-button type="primary" @click="saveDevice">保存设备</el-button></template></el-dialog>
<el-dialog v-model="detailDialog" title="设备详情" width="720px"><div v-if="detailData.device" class="detail-grid"><div><b>设备编号</b><span>{{detailData.device.code}}</span></div><div><b>设备名称</b><span>{{detailData.device.name}}</span></div><div><b>设备类型</b><span>{{detailData.device.type}}</span></div><div><b>生产厂家</b><span>{{detailData.device.manufacturer}}</span></div></div><h4>维修记录</h4><el-table :data="detailData.maintains" size="small"><el-table-column prop="faultDescription" label="故障描述"/><el-table-column prop="maintainer" label="维修人员"/><el-table-column prop="reportTime" label="报修时间"/><el-table-column prop="cost" label="费用"/></el-table><h4>最近采集数据</h4><el-table :data="detailData.weather" size="small"><el-table-column prop="collectTime" label="采集时间"/><el-table-column prop="temperature" label="温度"/><el-table-column prop="humidity" label="湿度"/><el-table-column prop="pressure" label="气压"/></el-table></el-dialog>
<el-dialog v-model="stationDialog" title="新增气象站点" width="520px"><el-form label-width="90px"><el-form-item label="站点名称"><el-input v-model="stationForm.name" placeholder="例如：北湖气象站"/></el-form-item><el-form-item label="站点地址"><el-input v-model="stationForm.address"/></el-form-item><el-form-item label="经度"><el-input-number v-model="stationForm.longitude" :precision="6" :step="0.001"/></el-form-item><el-form-item label="纬度"><el-input-number v-model="stationForm.latitude" :precision="6" :step="0.001"/></el-form-item><el-form-item label="负责人"><el-input v-model="stationForm.manager"/></el-form-item></el-form><template #footer><el-button @click="stationDialog=false">取消</el-button><el-button type="primary" @click="saveStation">保存站点</el-button></template></el-dialog>
<el-dialog v-model="maintainDialog" title="新建维修工单" width="520px"><el-form label-width="90px"><el-form-item label="设备 ID"><el-input-number v-model="maintainForm.deviceId" :min="1"/></el-form-item><el-form-item label="故障描述"><el-input v-model="maintainForm.faultDescription" type="textarea"/></el-form-item><el-form-item label="维修内容"><el-input v-model="maintainForm.content" type="textarea"/></el-form-item><el-form-item label="费用"><el-input-number v-model="maintainForm.cost" :min="0" :precision="2"/></el-form-item><el-form-item label="维修人员"><el-input v-model="maintainForm.maintainer"/></el-form-item></el-form><template #footer><el-button @click="maintainDialog=false">取消</el-button><el-button type="primary" @click="saveMaintain">提交工单</el-button></template></el-dialog>
<el-dialog v-model="weatherDialog" title="模拟上传气象数据" width="560px"><el-form label-width="100px"><el-form-item label="设备 ID"><el-input-number v-model="weatherForm.deviceId" :min="1"/></el-form-item><el-form-item label="温度(°C)"><el-input-number v-model="weatherForm.temperature" :precision="1"/></el-form-item><el-form-item label="湿度(%)"><el-input-number v-model="weatherForm.humidity" :min="0" :max="100" :precision="1"/></el-form-item><el-form-item label="风速(m/s)"><el-input-number v-model="weatherForm.windSpeed" :min="0" :precision="1"/></el-form-item><el-form-item label="降雨量(mm)"><el-input-number v-model="weatherForm.rainfall" :min="0" :precision="1"/></el-form-item><el-form-item label="气压(hPa)"><el-input-number v-model="weatherForm.pressure" :precision="1"/></el-form-item></el-form><template #footer><el-button @click="weatherDialog=false">取消</el-button><el-button type="primary" @click="saveWeather">上传数据</el-button></template></el-dialog>
<el-dialog v-model="planDialog" title="新增保养计划" width="520px"><el-form label-width="100px"><el-form-item label="设备 ID"><el-input-number v-model="planForm.deviceId" :min="1"/></el-form-item><el-form-item label="计划名称"><el-input v-model="planForm.title"/></el-form-item><el-form-item label="周期(天)"><el-input-number v-model="planForm.cycleDays" :min="1"/></el-form-item><el-form-item label="下次保养"><el-date-picker v-model="planForm.nextDate" value-format="YYYY-MM-DD" type="date"/></el-form-item><el-form-item label="负责人"><el-input v-model="planForm.owner"/></el-form-item><el-form-item label="备注"><el-input v-model="planForm.remark" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="planDialog=false">取消</el-button><el-button type="primary" @click="savePlan">保存计划</el-button></template></el-dialog></template>
