.analysis-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;padding:22px}.analysis-cards div{background:#f4f8fb;border:1px solid #e7edf3;border-radius:10px;padding:16px}.analysis-cards small{display:block;color:#8996a6;font-size:11px}.analysis-cards strong{display:block;font-size:26px;color:#172b4d;margin-top:8px}.muted{color:#9aa6b5;font-size:12px}.detail-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;background:#f5f8fb;padding:16px;border-radius:8px}.detail-grid b{display:block;color:#8996a6;font-size:11px}.detail-grid span{display:block;color:#172b4d;margin-top:5px}h4{font-size:13px;margin:18px 0 8px}.login-page{isolation:isolate}.weather-scene{position:absolute;inset:0;overflow:hidden;pointer-events:none}.weather-orbit{position:absolute;border:1px solid rgba(112,210,219,.16);border-radius:50%;transform:rotate(-18deg)}.orbit-one{width:900px;height:360px;right:-160px;top:6%;}.orbit-two{width:680px;height:270px;right:-40px;top:18%;border-color:rgba(255,255,255,.1)}.cloud{position:absolute;width:210px;height:58px;border-radius:50px;background:rgba(151,210,218,.08);filter:blur(1px)}.cloud:before,.cloud:after{content:"";position:absolute;border-radius:50%;background:inherit}.cloud:before{width:92px;height:92px;left:30px;top:-38px}.cloud:after{width:72px;height:72px;right:30px;top:-24px}.cloud-a{right:8%;top:28%;opacity:.8}.cloud-b{left:4%;bottom:18%;transform:scale(.72);opacity:.45}.rain-lines{position:absolute;right:16%;top:32%;width:170px;height:170px;background:repeating-linear-gradient(112deg,transparent 0 18px,rgba(102,198,208,.25) 19px 20px,transparent 21px 38px);transform:skewX(-15deg);mask-image:linear-gradient(to bottom,transparent,#000 28%,transparent)}.weather-meta{position:absolute;left:7vw;bottom:9vh;z-index:1;display:flex;gap:34px;color:#d3e7ec}.weather-meta div{display:grid;gap:4px}.weather-meta strong{font-size:25px;font-weight:500;letter-spacing:.5px}.weather-meta span{font-size:11px;color:#7ea0ad;letter-spacing:1px}.logi