;color:#ffd47a}.weather-banner-main span{display:block;font-size:11px;letter-spacing:.7px;color:#b9dcd9}.weather-banner-main strong{display:block;font-size:38px;line-height:1.1;margin:6px 0 2px;font-weight:600}.weather-banner-main sup{font-size:17px;margin-left:2px}.weather-banner-main small{font-size:11px;color:#b5d2d3}.weather-banner-data{display:flex;gap:24px;position:relative;z-index:1}.weather-banner-data>div{display:flex;align-items:center;gap:8px;min-width:100px;padding-left:16px;border-left:1px solid rgba(222,249,245,.2)}.weather-banner-data .el-icon{font-size:19px;color:#a7e5da}.weather-banner-data span{display:grid;gap:3px;font-size:10px;color:#afd1d0}.weather-banner-data b{font-size:12px;color:#f2fbf8}.metric{transition:transform .2s ease,box-shadow .2s ease}.metric:hover{transform:translateY(-3px);box-shadow:0 12px 24px rgba(29,77,96,.16)}.metric .el-icon{background:rgba(255,255,255,.13);border-radius:12px;padding:9px;box-sizing:content-box}.nav-item .el-icon{width:17px;height:17px;display:grid;place-items:center;padding:5px;border-radius:7px;background:rgba(255,255,255,.045)}.nav-item.active .el-icon{background:rgba(36,193,162,.16);color:#59e0c4}.panel{backdrop-filter:blur(2px)}.table-panel .toolbar b:before{content:"";display:inline-block;width:5px;height:16px;border-radius:3px;background:#24c1a2;margin-right:9px;vertical-align:-3px}.panel-head b:before{content:"";display:inline-block;width:5px;height:14px;border-radius:3px;background:#24c1a2;margin-right:8px;vertical-align:-2px}@media(max-width:1100px){.weather-banner-data{gap:10px}.weather-banner-data>div{min-width:82px;padding-left:10px}}@media(max-width:760px){.header-weather{display:none}.weather-banner{align-items:flex-start;gap:18px;flex-direction:column}.weather-banner-data{width:100%;justify-content:space-between}.weather-banner-data>div{flex:1;min-width:0}.weather-meta{left:5vw;bottom:4vh}.weather-meta strong{font-size:19px}}</style>
